   replacement.Project=Project;replacement.Dance=Dance;replacement.CameraClip=CameraClip;replacement.Audio=Audio;replacement.Rig=Rig;replacement.projectPath=projectPath;replacement.dirty=dirty;replacement.cursor=cursor;replacement.modRoot=modRoot;
