 public async Task LoadProject(SongProject p){
  Stop();ProjectRules.Validate(p);foreach(var declared in new[]{p.Dance,p.Camera,p.Audio})if(declared.Path.Length>0&&!File.Exists(declared.Path))throw new FileNotFoundException(UiText.T("t0196")+declared.Path);SetBusy(true,UiText.T("t0197"));
  try {
   // Keep the current project, assets and save destination intact until all reads succeed.
   if(!DanceStudio.Rig.IsBuiltin(p.Skeleton)&&!File.Exists(p.Skeleton)){p.Skeleton=DanceStudio.Rig.BuiltinId;status.Text=UiText.T("t0198");}var loadedRig=await Task.Run(()=>DanceStudio.Rig.Load(p.Skeleton));var loadedDance=File.Exists(p.Dance.Path)?await LoadMotion(p.Dance.Path,p.Dance.HkxBindingIndex,p.Dance.IdentityRigProof,loadedRig):null;var loadedCamera=File.Exists(p.Camera.Path)?await LoadMotion(p.Camera.Path,p.Camera.HkxBindingIndex,p.Camera.IdentityRigProof,loadedRig):null;var loadedAudio=File.Exists(p.Audio.Path)?await Task.Run(()=>AudioImport.Load(p.Audio.Path)):null;var loaded=(rig:loadedRig,dance:loadedDance,cam:loadedCamera,audio:loadedAudio);if(loadedDance!=null){p.Dance.HkxBindingIndex=loadedDance.BindingIndex;p.Dance.IdentityRigProof=loadedDance.IdentityRigProof;}if(loadedCamera!=null){p.Camera.HkxBindingIndex=loadedCamera.BindingIndex;p.Camera.IdentityRigProof=loadedCamera.IdentityRigProof;if(p.CameraBone>=loadedRig.Names.Length)throw new InvalidDataException(UiText.T("t0199"));}

   Project=p;Rig=loaded.rig;Dance=loaded.dance;CameraClip=loaded.cam;Audio=loaded.audio;projectPath=null;
   stage.SetRig(Rig);camera.SetRig(Rig);updating=true;try{bones.ItemsSource=Rig.Names.Select((name,i)=>new BoneItem(i,name)).ToList();}finally{updating=false;}
   if(p.CameraBone<0&&CameraClip!=null)AutoCamera();timeline.Span=Math.Max(10,Math.Max(p.ExportOut,Math.Max(p.Dance.TimelineEnd,Math.Max(p.Camera.TimelineEnd,p.Audio.TimelineEnd)))*1.03);timeline.ViewStart=0;
   Seek(p.ExportIn);RefreshFields();dirty=false;SetBusy(false,AllReady?UiText.T("t0200"):UiText.T("t0201"));
  }catch{SetBusy(false,UiText.T("t0202"));throw;}
