 void ReadSettings(){if(updating||busy)return;ReadVolume();double Read(TextBox b,double old)=>double.TryParse(b.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out var v)&&double.IsFinite(v)?v:old;double Rate(TextBox b,double old){double value=Read(b,old);if(value<.05||value>8)return old;return value;}double oldDanceSpeed=Project.Dance.Speed,oldCameraSpeed=Project.Camera.Speed;Project.Dance.Speed=Rate(danceSpeed,Project.Dance.Speed);Project.Camera.Speed=Rate(cameraSpeed,Project.Camera.Speed);if(oldDanceSpeed!=Project.Dance.Speed||oldCameraSpeed!=Project.Camera.Speed)FitRateTimeline();Project.CameraHeightOffset=Math.Clamp(Read(heightOffset,Project.CameraHeightOffset),-20000,20000);Project.Fov=Math.Clamp(Read(fov,Project.Fov),5,140);Project.CameraYaw=ProjectRules.NormalizeYaw(Read(yaw,Project.CameraYaw));Project.PreviewAspectRatio=Math.Clamp(Read(aspect,Project.PreviewAspectRatio),ProjectRules.MinAspect,ProjectRules.MaxAspect);camera.SetAspect(Project.PreviewAspectRatio);Project.PlayerYaw=NormalizeYaw(Read(playerYaw,Project.PlayerYaw));Project.ExportIn=Math.Max(0,Read(outIn,Project.ExportIn));Project.ExportOut=Math.Max(Project.ExportIn+.001,Read(outOut,Project.ExportOut));Changed();}
