 public void CleanForSmoke(){dirty=false;}
 public async Task<object> TransportSmoke(){
  silentTest=true;Seek(25);Toggle();await Task.Delay(240);bool advancing=cursor>25.05&&cursor<27;
  bool hardwareClock=sound.Active;double observed=cursor;Stop();Seek(25+1.0/Project.DanceOutputFps.Resolve(Dance,Project.Dance));
  if(!advancing)throw new Exception(UiText.T("t0244"));
  if(Math.Abs(cursor-(25+1.0/Project.DanceOutputFps.Resolve(Dance,Project.Dance)))>1e-8)throw new Exception(UiText.T("t0245"));
  silentTest=false;dirty=false;return new {passed=true,hardwareClock,observedTimeline=observed,frameStep=1.0/Project.DanceOutputFps.Resolve(Dance,Project.Dance),silentAudio=true};
 }
